    ("Convert source types with rejects", "Type conversion", "Convert integer fields and separate malformed rows instead of silently dropping them.", "rows = [{'id': '1'}, {'id': 'x'}]", "rows = [{'id': '1'}, {'id': 'x'}]\nvalid, rejected = [], []\nfor row in rows:\n    try:\n        valid.append({'id': int(row['id'])})\n    except (TypeError, ValueError):\n        rejected.append(row)\nprint(valid, rejected)", "[{'id': 1}] [{'id': 'x'}]", "[{'id': 1}] [{'id': 'x'}]"),
    ("Aggregate nested line items", "Nested JSON", "Compute an order total from nested line items, treating a missing quantity as one.", "order = {'items': [{'price': 3, 'quantity': 2}, {'price': 5}]}", "order = {'items': [{'price': 3, 'quantity': 2}, {'price': 5}]}\ntotal = sum(item['price'] * item.get('quantity', 1) for item in order['items'])\nprint(total)", "11", 11),
