    ("Join rows using a lookup map", "Joins", "Enrich order rows with customer names using a precomputed dictionary lookup.", "orders = [{'customer_id': 1, 'amount': 9}]\ncustomers = [{'id': 1, 'name': 'Mina'}]", "orders = [{'customer_id': 1, 'amount': 9}]\ncustomers = [{'id': 1, 'name': 'Mina'}]\nlookup = {c['id']: c['name'] for c in customers}\nprint([{**o, 'customer_name': lookup.get(o['customer_id'])} for o in orders])", "[{'customer_id': 1, 'amount': 9, 'customer_name': 'Mina'}]", [{"customer_id": 1, "amount": 9, "customer_name": "Mina"}]),
