    ("CSV to database ETL", "etl", "Build a restartable batch pipeline from CSV delivery to a relational warehouse table.", "Python", ["Inspect source headers and define an explicit schema.", "Parse and validate records, sending rejects to a quarantine output.", "Load into a staging table, then merge by the natural key."], ["Valid row count matches the source minus rejects.", "Re-running the same batch produces no duplicate business keys.", "A failed load can be resumed from its committed checkpoint."], {"file": "orders.csv", "columns": ["order_id", "customer_id", "amount", "updated_at"], "rows": [["o-1", "c-1", "42.50", "2025-01-02T10:00:00"], ["o-2", "c-2", "bad", "2025-01-02T10:03:00"]]}),
    ("REST API ingestion", "python", "Ingest a paginated REST endpoint with rate-limit awareness, retries, and idempotent storage.", "Python", ["Define request timeouts and retry only transient failures.", "Follow pagination tokens and persist raw response metadata.", "Normalize records and deduplicate by source id."], ["All pages are consumed exactly once per checkpoint.", "429 and 5xx responses back off without dropping records.", "A replay does not duplicate stored source ids."], {"pages": [{"next": "p2", "items": [{"id": 1, "updated": "2025-01-01"}]}, {"next": None, "items": [{"id": 2, "updated": "2025-01-02"}]}]}),
