    ("Data quality validation", "python", "Create a reusable validation stage that records rule outcomes and quarantines invalid rows.", "Python", ["Define schema, null, uniqueness, and referential-integrity rules.", "Separate hard failures from warning-level metrics.", "Persist rejected rows with rule identifiers."], ["Each rejection has a stable reason code.", "Valid and rejected counts reconcile to input count.", "Threshold violations fail the batch before publication."], {"rows": [{"id": 1, "email": "a@example.com"}, {"id": None, "email": "bad"}]}),
    ("SCD Type 2 customer pipeline", "sql", "Maintain historical customer attributes with effective dates and exactly one current version.", "SQL", ["Compare incoming tracked attributes with current dimension rows.", "Expire changed versions and append new versions transactionally.", "Handle unchanged records and previously unseen business keys."], ["History is preserved for changed attributes.", "Unchanged customers do not gain redundant versions.", "Each known business key has one current row."], {"current": [{"customer_id": "c1", "city": "Pune", "valid_from": "2024-01-01", "valid_to": None, "is_current": True}], "incoming": [{"customer_id": "c1", "city": "Delhi"}]}),
    ("Fact and dimension modelling", "sql", "Model an order analytics mart with a transaction-grain fact and conformed customer, product, and date dimensions.", "SQL", ["State grain before selecting measures and keys.", "Define surrogate keys and unknown-member behavior.", "Load dimensions before facts and validate referential integrity."], ["Fact row count matches eligible source order lines.", "Measures aggregate at the declared grain.", "Dimension keys resolve, including late-arriving entities."], {"order_lines": [{"order_id": "o1", "line_id": 1, "customer_id": "c1", "product_id": "p1", "quantity": 2, "unit_price": 5}]}),
    ("Log processing and sessionization", "pyspark", "Parse semi-structured application logs, reject malformed events, and derive user sessions.", "PySpark", ["Parse JSON with a schema and preserve corrupt records.", "Order events by user and timestamp; start a new session after an inactivity gap.", "Aggregate session duration and event count."], ["Malformed logs are measurable and retained for review.", "Session boundaries use deterministic event ordering.", "Aggregates match hand-checked sample sessions."], {"events": [{"user_id": "u1", "event_time": "2025-01-01T10:00:00", "type": "view"}, {"user_id": "u1", "event_time": "2025-01-01T10:20:00", "type": "buy"}]}),
    ("Large-file processing", "python", "Process a file larger than memory using bounded batches and observable checkpoints.", "Python", ["Stream input without loading the complete file.", "Validate and transform each bounded chunk.", "Write deterministic partitioned output and checkpoint only committed chunks."], ["Peak memory stays bounded as input size grows.", "A failed chunk can be retried without duplicate output.", "Metrics identify throughput, rejects, and checkpoint position."], {"file_size": "multi-gigabyte", "batch_rows": 50000, "record": {"id": "r1", "payload": "..."}}),
    ("PySpark transformations", "pyspark", "Build a typed DataFrame pipeline that cleans order events and produces customer-level metrics.", "PySpark", ["Declare an explicit schema and parse timestamps.", "Filter invalid rows, deduplicate deterministically, and join customer attributes.", "Aggregate daily metrics and write partitioned Parquet."], ["Transformations preserve row-level lineage for rejects.", "Output schema and partition columns are documented.", "The physical plan has no unnecessary wide transformations."], {"orders": [{"order_id": "o1", "customer_id": "c1", "amount": 20.0, "updated_at": "2025-01-01T12:00:00"}]}),
